package br.edu.ifc.treinoecapacitacao.view;
import br.edu.ifc.treinoecapacitacao.App; import br.edu.ifc.treinoecapacitacao.model.*; import javafx.geometry.*; import javafx.scene.*; import javafx.scene.control.*; import javafx.scene.layout.*; import javafx.stage.Stage; import java.time.LocalDate; import java.time.format.DateTimeFormatter;
public class TelaCertificados { private Stage stage; public TelaCertificados(Stage stage){this.stage=stage;} public Scene criarCena(){Label titulo=new Label("Certificados");titulo.setId("tituloTreinamentos");ListView<Participacao> participacoes=new ListView<Participacao>(App.participacoes);participacoes.setPrefHeight(220);ListView<Certificado> certificados=new ListView<Certificado>(App.certificados);certificados.setPrefHeight(180);Button emitir=new Button("Emitir certificado");emitir.getStyleClass().add("botao-principal");Button voltar=new Button("Voltar");emitir.setOnAction(e->{Participacao p=participacoes.getSelectionModel().getSelectedItem();if(p==null){new Alert(Alert.AlertType.WARNING,"Selecione uma participação.").show();return;}if(!p.getStatus().equals("Concluído")){new Alert(Alert.AlertType.WARNING,"O participante precisa estar concluído.").show();return;}for(Certificado c:App.certificados)if(c.getParticipacao()==p){new Alert(Alert.AlertType.WARNING,"Já existe certificado para esta participação.").show();return;}String data=LocalDate.now().format(DateTimeFormatter.ofPattern("dd/MM/yyyy"));Certificado c=new Certificado(p,data,p.getTreinamento().getCargaHoraria());App.certificados.add(c);App.historico.add("Certificado emitido: "+p.getBombeiro().getNome());});voltar.setOnAction(e->{stage.setScene(new TelaDashboard(stage).criarCena());stage.setTitle("Painel - Treinamento e Capacitação");});VBox raiz=new VBox(12,titulo,new Label("Participações"),participacoes,new HBox(8,emitir,voltar),new Label("Certificados emitidos"),certificados);raiz.setPadding(new Insets(22));raiz.setAlignment(Pos.TOP_CENTER);Scene scene=new Scene(raiz,800,600);scene.getStylesheets().add("/css/style.css");return scene;} }
